red=0
for br in BREAKS:
    name,f,a,b,test=br[:5]; env=dict(os.environ, **(br[5] if len(br)>5 else {}))
    p=R+f; s=open(p).read()
    assert s.count(a)==1,(name,s.count(a))
    open(p,'w').write(s.replace(a,b))
    try:
        r=subprocess.run(["npx","vitest","run",test],cwd=R,env=env,capture_output=True,text=True,timeout=600)
        ok = r.returncode!=0
    finally:
        open(p,'w').write(s)
    red+=ok
    print(("RED  " if ok else "GREEN (missed) ")+name+(" [SCANNER_GATE=1]" if len(br)>5 else ""), flush=True)
print(f"{red}/{len(BREAKS)} breaks caught")
